{"ts":"2026-09-19T21:13:14.116+03:00","v":"1","level":"DEBUG","logger":"org.hibernate.SQL","thread":"Test worker","msg":"SELECT a.*
FROM assignments a
JOIN semesters existing_semester ON existing_semester.id = a.semester_id
WHERE a.teacher_id = ?
  AND a.subject_id = ?
  AND a.group_id = ?
  AND a.semester_id = ?
