  AND daterange(
        a.valid_from,
        COALESCE(a.valid_until_exclusive, existing_semester.date_to + 1),
        '[)'
      ) && daterange(
        CAST(? AS date),
        COALESCE(CAST(? AS date), existing_semester.date_to + 1),
        '[)'
      )
LIMIT 1
","traceId":"37eef2beb28ec39c9260156e96714d98","service":"academic-service"}
